import { getProviderConfig } from './providers';
import type { ProviderId, ServiceTab } from './types';

export interface CreateTabOptions {
  /** UUID generated by the caller so this helper stays pure/testable. */
  id: string;
  providerId: ProviderId;
  customUrl?: string;
  label?: string;
  /** Number of tabs that already use this provider, used for "Gemini 2" labels. */
  existingCount: number;
  now?: Date;
}

export function normalizeServiceUrl(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) return '';
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(trimmed)) return trimmed;
  return `https://${trimmed}`;
}

export function createServiceTab(options: CreateTabOptions): ServiceTab {
  const provider = getProviderConfig(options.providerId);
  const customUrl = options.customUrl ? normalizeServiceUrl(options.customUrl) : '';
  const url = customUrl || provider.url;

  if (!url) throw new Error('A URL is required for a custom service');

  const baseLabel = options.label?.trim() || provider.displayName;
  const label = options.existingCount > 0 ? `${baseLabel} ${options.existingCount + 1}` : baseLabel;

  return {
    id: options.id,
    providerId: provider.id,
    label,
    url,
    partition: `persist:service-${options.id}`,
    color: provider.color,
    icon: provider.icon,
    createdAt: (options.now ?? new Date()).toISOString()
  };
}
